CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE profiles(id TEXT PRIMARY KEY,username TEXT NOT NULL,display_name TEXT NOT NULL,bio TEXT DEFAULT '',avatar_url TEXT,created_at TEXT NOT NULL);
CREATE TABLE games(id TEXT PRIMARY KEY,name TEXT NOT NULL,genre TEXT DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE profile_games(profile_id TEXT NOT NULL,game_id TEXT NOT NULL,platform TEXT DEFAULT 'manual',PRIMARY KEY(profile_id,game_id));
CREATE TABLE communities(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,description TEXT DEFAULT '',visibility TEXT DEFAULT 'public',game_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE community_members(community_id TEXT NOT NULL,profile_id TEXT NOT NULL,role TEXT DEFAULT 'member',PRIMARY KEY(community_id,profile_id));
CREATE TABLE guilds(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT DEFAULT '',game_id TEXT,region TEXT,recruiting INTEGER DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE guild_members(guild_id TEXT NOT NULL,profile_id TEXT NOT NULL,role TEXT DEFAULT 'member',PRIMARY KEY(guild_id,profile_id));
CREATE TABLE events(id TEXT PRIMARY KEY,host_id TEXT NOT NULL,title TEXT NOT NULL,starts_at TEXT NOT NULL,description TEXT DEFAULT '',game_id TEXT,community_id TEXT,guild_id TEXT,capacity INTEGER,created_at TEXT NOT NULL);
CREATE TABLE event_attendees(event_id TEXT NOT NULL,profile_id TEXT NOT NULL,status TEXT DEFAULT 'going',PRIMARY KEY(event_id,profile_id));
CREATE TABLE posts(id TEXT PRIMARY KEY,author_id TEXT NOT NULL,body TEXT NOT NULL,community_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL,author_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE friendships(requester_id TEXT NOT NULL,addressee_id TEXT NOT NULL,status TEXT DEFAULT 'pending',created_at TEXT NOT NULL,PRIMARY KEY(requester_id,addressee_id));
CREATE TABLE direct_conversations(id TEXT PRIMARY KEY,created_by TEXT NOT NULL,title TEXT,is_group INTEGER DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE direct_conversation_members(conversation_id TEXT NOT NULL,profile_id TEXT NOT NULL,PRIMARY KEY(conversation_id,profile_id));
CREATE TABLE direct_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,author_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE voice_rooms(id TEXT PRIMARY KEY,name TEXT NOT NULL,community_id TEXT,guild_id TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE platform_connections(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,provider TEXT NOT NULL,provider_user_id TEXT,display_name TEXT,status TEXT DEFAULT 'pending',connected_at TEXT,UNIQUE(profile_id,provider));
CREATE TABLE lfg_posts(id TEXT PRIMARY KEY,author_id TEXT NOT NULL,game_id TEXT NOT NULL,platform TEXT,region TEXT,play_style TEXT,description TEXT NOT NULL,expires_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX idx_posts_created ON posts(created_at);
CREATE INDEX idx_direct_messages ON direct_messages(conversation_id,created_at);
